// list and the digest, while release_ts and posted_date survive as history — useful if
// Accounting ever asks why a QU has no release.
//
// UNTRACKED rows have no qu_number, so appendOrUpdate cannot match them and they cannot
// be cleaned this way. Rare, and they are already excluded from every count.
const req = $('Classify Event').first().json;
const rows = $input.all().map((i) => i.json);

const row = rows.find((r) =>
  String(r.source_ts || '').trim() === String(req.deleted_ts).trim());

if (!row) return [{ json: { kind: 'NOOP', reason: 'no index row for deleted ts ' + req.deleted_ts } }];
if (!row.qu_number)
  return [{ json: { kind: 'NOOP', reason: 'untracked row has no key to update' } }];
if (String(row.status || '').trim() === 'DELETED')
  return [{ json: { kind: 'NOOP', reason: 'row is already DELETED' } }];

return [{ json: { kind: 'MARK', qu_number: row.qu_number, status: 'DELETED',
                  was_status: row.status || '', last_seen: new Date().toISOString() } }];

// Strip the routing key so only the columns we mean to change are written.
const r = $input.first().json;
return [{ json: { qu_number: r.qu_number, status: r.status, last_seen: r.last_seen } }];

// Revert a release whose #releaseme post was deleted.
//
// Only rows that are actually RELEASED, matched on release_ts — the ts of the message
// Posty created. A CANCELLED row is left alone: deleting the cancellation notice does not
// un-cancel a project.
//
// notify_ts is deliberately kept. The DM Posty sent still exists, so rocketing it again
// must still resolve to this project — that is the whole point of an undo.
const req = $('Classify Event').first().json;
const rows = $input.all().map((i) => i.json);

const row = rows.find((r) =>
  String(r.release_ts || '').trim() === String(req.deleted_ts).trim());

if (!row) return [{ json: { kind: 'NOOP', reason: 'no row released as ts ' + req.deleted_ts } }];
if (String(row.status || '').trim() !== 'RELEASED')
  return [{ json: { kind: 'NOOP', reason: 'row is ' + row.status + ', not reverting' } }];
if (!row.qu_number)
  return [{ json: { kind: 'NOOP', reason: 'no qu_number to match on' } }];

return [{ json: { kind: 'REVERT', qu_number: row.qu_number,
                  status: 'OPEN', released: 'FALSE',
                  release_ts: '', release_date: '',
                  last_seen: new Date().toISOString() } }];

// Strip the routing key; write only the columns being reverted.
const r = $input.first().json;
return [{ json: { qu_number: r.qu_number, status: r.status, released: r.released,
                  release_ts: r.release_ts, release_date: r.release_date,
                  last_seen: r.last_seen } }];

// Hand the requester to Workflow 3. It resolves recipients itself, so the digest a
// person asks for is built by exactly the same code as the scheduled one.
//
// Read from Classify Event by name, NOT from $input. Reading $input meant that inserting
// any node upstream silently replaced the payload — an ack reaction did exactly that, the
// user went undefined, and Workflow 3 fell through to its scheduled gate and sent nothing.
return [{ json: { user: $('Classify Event').first().json.user } }];

// Explain a drop to whoever reacted. A rocket that does nothing is the single most
// confusing thing Posty can do — the person cannot tell the difference between "already
// handled" and "broken", so they either react again or assume it failed silently.
const r = $('Resolve Release').first().json;
const row = r.row || {};

const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function humanDate(iso) {
  const m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return m ? Number(m[3]) + ' ' + MONTHS[Number(m[2]) - 1] + ' ' + m[1] : '';
}

const label = row.qu_number
  ? (String(row.qu_number).startsWith('NOQU-') ? 'That project' : 'QU-' + row.qu_number)
  : 'That project';

let text;
if (r.decision === 'DROP_STUDIOM') {
  text = label + ' is a Studio M recording, so it is logged but not tracked for release — '
       + 'nothing to repost. Nothing to do.';
} else if (r.decision === 'DROP_CANCELLED') {
  text = label + ' is marked cancelled, so I have not reposted it. If that is wrong, '
       + 'let Tara know and the row can be reopened.';
} else {
  const when = humanDate(row.release_date);
  text = label + ' was already released' + (when ? ' on ' + when : '')
       + ', so I have not reposted it. Nothing to do.';
}

return [{ json: { user: $('Slack Trigger').first().json.user, text } }];

// The reacted-to post is not in the index, so there is nothing to repost.
//
// Worded as an instruction rather than a promise: §7 step 4 describes an automatic retry
// after the nightly refresh, and that retry is NOT built. Telling someone to wait for
// something that will not happen is worse than telling them to react again.
const e = $('Slack Trigger').first().json;
return [{ json: { user: e.user,
  text: "I don't have that post in the index yet, so I can't repost it — I've parked it. "
      + "This usually means the post arrived while I was down. React with 🚀 or ✅ again after the "
      + "02:00 refresh tonight and it should go through." } }];

// Build the target engineer's open-project blast: an intro, then one message per open
// project so each can be reacted to. Emits nothing when the engineer has no open work.
const cfg = $('Classify Event').first().json;
const rows = $input.all().map((i) => i.json);
const target = String(cfg.target_user).trim();
function esc(t){ return String(t==null?'':t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const mine = rows.filter((r) =>
  String(r.posted_by||'').trim()===target &&
  String(r.status||'').trim()==='OPEN' &&
  String(r.qu_number||'').trim()!=='');
mine.sort((a,b)=>String(a.posted_date).localeCompare(String(b.posted_date)));
if(!mine.length) return [];
const intro = "Hi "+cfg.target_name+" 👋 It's Posty. Here are your projects that still need closing.\n\n"
  + "For each one that's finished:\n1. Tap 🚀 or ✅ on it — I'll mark it released.\n"
  + "2. Reply to that same message with the release details.\n\nThat's it 🙏";
const out=[{ json:{ is_header:true, qu_number:'', text:intro, target_user:target } }];
for(const r of mine) out.push({ json:{ is_header:false, qu_number:r.qu_number, text:esc(r.source_text), target_user:target } });
return out;

// Record each blasted message's ts as that project's notify_ts, so the engineer's reaction
// on it resolves back to the project. Pair responses to inputs by order.
const inputs = $('Build Remind List').all().map((i)=>i.json);
const resps = $input.all().map((i)=>i.json);
function slackTs(r){ return String(r.message_timestamp || (r.message && r.message.ts) || '').trim(); }
const out=[];
for(let i=0;i<resps.length;i++){
  const src=inputs[i];
  if(!src || src.is_header || !src.qu_number) continue;
  const ts=slackTs(resps[i]); if(!ts) continue;
  out.push({ json:{ qu_number:src.qu_number, notify_ts:ts, last_seen:new Date().toISOString() } });
}
return out;

// One confirmation back to Tara, whether or not the engineer had open work.
const cfg = $('Classify Event').first().json;
const rows = $('Read Index (Remind)').all().map((i)=>i.json);
const target = String(cfg.target_user).trim();
const n = rows.filter((r) =>
  String(r.posted_by||'').trim()===target &&
  String(r.status||'').trim()==='OPEN' &&
  String(r.qu_number||'').trim()!=='').length;
const text = n>0
  ? ('Sent '+cfg.target_name+' their '+n+' open project'+(n===1?'':'s')+'.')
  : (cfg.target_name+' has no open projects — nothing sent.');
return [{ json:{ user:cfg.requester, text } }];

const cfg = $('Classify Event').first().json;
return [{ json:{ user:cfg.requester,
  text:"I don't know an engineer called \""+cfg.name+"\". Try their first name, e.g. remind glenn." } }];

// Hand the requester to Workflow 5. It resolves mode itself: a request carries a
// user, so it runs in PREVIEW and DMs the result back rather than posting publicly.
// Read from Classify Event by name, not $input, for the same reason Emit Digest does.
return [{ json: { user: $('Classify Event').first().json.user } }];

// One confirmation for Tara, however many canvases were rewritten.
const n = ($input.first().json || {}).refreshed || 0;
return [{ json: { user: $('Classify Event').first().json.user,
  text: 'Refreshed ' + n + ' Tracker canvas' + (n === 1 ? '' : 'es') + '.' } }];

// A release admin (Tara) released someone else's project: tell the engineer, so it doesn't
// happen silently, and ask them for the release details (they know them, Tara may not).
// "didn't go through" covers both a reaction Slack lost and one never made; it blames no one.
// Tara, 2026-09-28. Nothing is emitted for an ordinary release by the poster.
const resolved = $('Resolve Release').first().json;
const row = resolved.row || {};
const reactor = String($('Slack Trigger').first().json.user || '').trim();
const poster = String(row.posted_by || '').trim();
if (!/^[UW][A-Z0-9]+$/.test(poster) || !reactor || poster === reactor) return [];

const posted = $input.first().json;
const ts = String(posted.message_timestamp || (posted.message && posted.message.ts) || '').trim();
const link = /^\d+\.\d+$/.test(ts) ? 'https://hitproductions.slack.com/archives/CC9EG3K8C/p' + ts.replace('.', '') : '';
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const line = String(row.source_text || '').split('\n')[0].trim();
const slash = line.indexOf('/');
const what = slash !== -1 ? line.slice(slash + 1).trim() : '';
const title = what ? ' (' + esc(what.length > 80 ? what.slice(0, 79) + '…' : what) + ')' : '';
return [{ json: { user: poster, text:
  "Heads up: your release for *QU-" + row.qu_number + "*" + title + " didn't go through, so Tara released it for you. " +
  "It's now posted in " + (link ? '<' + link + '|#releaseme>' : '#releaseme') + ".\n" +
  "Please reply to that post with the release details, same as usual." } }];

// Check the new post against Xero right away (Tara, 2026-09-28): Workflow 5 replies in-thread
// (typo flag or studio hours) and DMs Tara. It runs after the row is written, and Workflow 2 doesn't
// wait for it. If Slack never delivers the post, or this fails, the 09:00/17:00 runs still check it,
// and they skip any post Posty already replied to. An uncoded (NOQU-) post has nothing to look up.
const req = $('Classify Event').first().json;
if (req.synthetic) return [];
const e = $('Slack Trigger').first().json;
return [{ json: { post: { ts: String(e.ts || ''), text: e.text || '', user: e.user || '',
  bot_id: e.bot_id || '', app_id: e.app_id || '', subtype: e.subtype || '' } } }];
